    private static final List<Field> RAW_CHARACTER_FIELDS=List.of(ARMY_CHARACTER_120_RAW_U32,ARMY_UNIT_124_RAW_U32,UNIT_OWNER_174_RAW_U32,CHARACTER_MAGIC_1C_RAW_U32,CHARACTER_FULL_ID_18_RAW_U32,CHARACTER_DEATH_1D0_PRESENT,CHARACTER_STATE_1C8_PRESENT,CHARACTER_STATE_1C0_PRESENT,CHARACTER_STATE_1B8_PRESENT,FAILURE_APPEND_ARMY_10_RAW_U32);
