    private static boolean covered(Document raw,int size){Document refs=raw.object(ORIGINAL_ROSTER);return raw.yes(MANAGER_LOADED)&&refs.yes(REFERENCES_READY)&&Objects.equals(refs.i32(COUNT_RAW_I32),size);}
    public static CharacterProjection projectCharacter(Inputs input,ArmyManagersPending.Projection pending){if(input==null)return new CharacterProjection(false,false,false,false,false,List.of(),List.of(),List.of(),null,null,List.of(),"native_character_prefix_family_absent");validateCharacter(input);Document raw=input.value();List<CharacterDecision> original=raw.rows(OCCURRENCES).stream().map(ArmyManagersPrefixes::characterDecision).toList();boolean covered=covered(raw,original.size()),rawComplete=covered&&original.stream().allMatch(CharacterDecision::ready),continuous=true,dispatchComplete=true;Map<Integer,ArmyManagersPending.Decision> prior=pending.occurrences().stream().collect(Collectors.toMap(ArmyManagersPending.Decision::nativeIndex,Function.identity(),(first,last)->last));List<CharacterDecision> decisions=new ArrayList<>();List<CharacterRequest> prefix=new ArrayList<>(),independent=new ArrayList<>();List<Integer> admissions=new ArrayList<>();for(int i=0;i<original.size();i++){Document row=raw.rows(OCCURRENCES).get(i);CharacterDecision decision=original.get(i);Boolean skip=row.bool(EARLIER_SKIP);String source=row.text(EARLIER_SKIP_SOURCE);ArmyManagersPending.Decision joined=prior.get(decision.nativeIndex());if(joined!=null&&joined.ready()&&Objects.equals(joined.rawId(),row.integer(ORIGINAL_REQUEST_FULL_ID_U32))){skip=joined.skip();source="same_query_pending_projection";}dispatchComplete&=skip!=null;decision=decision.joined(skip,source);decisions.add(decision);if(!decision.ready())continuous=false;else if(Boolean.TRUE.equals(decision.append())){CharacterRequest request=new CharacterRequest(decision.nativeIndex(),decision.request(),decision.appendArmy(),decision.firstFailure());independent.add(request);if(continuous)prefix.add(request);}if(Boolean.TRUE.equals(decision.admission()))admissions.add(decision.nativeIndex());}boolean complete=covered&&decisions.stream().allMatch(CharacterDecision::ready),initialReady=listReady(raw.object(INITIAL_80),false);List<BigInteger> appended=complete?independent.stream().map(CharacterRequest::army).toList():null,logical=null;if(complete&&initialReady){logical=new ArrayList<>(raw.object(INITIAL_80).integers(ORDERED_IDS_U32));logical.addAll(appended);}return new CharacterProjection(true,rawComplete,initialReady,covered&&dispatchComplete,complete,decisions,prefix,independent,appended,logical,admissions,complete?null:"character_prefix_demanded_inputs_incomplete");}
    public static ObjectNode encodeDated(DatedProjection p){ObjectNode out=JsonNodeFactory.instance.objectNode();out.put("projection_kind","conditional_pre_date_2a9a360_logical_dated_append").put("conditional_append_requests_ready",p.complete()).put("clock_ready",p.current()!=null).put("initial_158_ready",p.initialReady()).put("logical_158_result_ready",p.logical()!=null);nullable(out,"current_date_raw_i32",p.current());nullable(out,"tomorrow_date_low_i32",p.tomorrow());ArrayNode prefix=out.putArray("request_prefix"),independent=out.putArray("independently_derived_requests");p.prefix().forEach(value->prefix.add(encodeDatedRequest(value)));p.independent().forEach(value->independent.add(encodeDatedRequest(value)));ids(out,"append_request_full_ids_u32",p.appended());ArrayNode rows=out.putArray("occurrences");for(DatedDecision d:p.occurrences()){ObjectNode row=rows.addObject().put("native_index",d.nativeIndex()).put("ready",d.ready());integer(row,"original_request_full_id_u32",d.request(),false);ArmyManagersPending.bool(row,"append",d.append());ArmyManagersPending.text(row,"branch",d.branch());nullable(row,"first_due_date_native_index",d.firstDue());reason(row,d.reason());}ids(out,"logical_158_full_ids_u32",p.logical());nullable(out,"logical_158_count_i32",p.logical()==null?null:p.logical().size());ArrayNode preserved=out.putArray("preserved_prefix_inputs");List.of("manager_50_5c","manager_68_74","manager_pending_130").forEach(preserved::add);out.put("actual_next_callback_ready",false).put("full_daily_assault_ready",false).put("remaining_character_unit_prefix_replayed",false).put("physical_growth_replayed",false).put("native_calls_executed",0).put("native_writes_executed",0);reason(out,p.reason());return out;}
